function UIActionPointMapDropMessagePopUpDialog:FillRewards()
    local _t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self.levelId)
    local t = {}

    local __t = {}
    for k, v in pairs(_t) do
        if not t[checkString(v.type)] then
            t[checkString(v.type)] = {
                sortKey = checkNumber(v.type),
                data = {}
            } 
            table.insert(__t, checkString(v.type))
        end

        table.insert(t[checkString(v.type)].data, v)
    end
    --local rewards = {}
    --for k, v in pairs(t) do
    --    table.insert(rewards, v)
    --end
    --table.sort(rewards, function(a, b)
    --    return checkNumber(a.sortKey) < checkNumber(b.sortKey)
    --end)

    for k, v in pairs(__t) do
        local data = t[checkString(v)]
        local go = CfUtils.InstantiateGo(self.FirstReward, self.cont)
        self:FillReward(go, data.data, data.sortKey)
    end
end

function UIActionPointMapDropMessagePopUpDialog:FillReward(go, data, type)
    if not data or not go then
        return
    end

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self.levelId)
    local parGo = go.transform:Find("items")
    local childGo = parGo.transform:Find("GoodNode")
    KTool.SetActive(childGo, false)

    local name = GoodsUtils.GetRewardSourceDesc(type)
    CfUtils.FillText(go.transform:Find("title/img/name"), name)
    CfUtils.SetActive(go, table.count(data) > 0)

    for k, v in pairs(data) do
        local _go = CfUtils.InstantiateGo(childGo, parGo)
        CfUtils.SetActive(_go, true)

        local num
        if checkNumber(v.num) > 0 then
            num = "x" .. v.num
        end
        CfUtils.RefeshGoodGo2(_go, v.id, num, nil, nil, function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.id)
            GameUtils.ShowCommonTipsBoard(_go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)
        if type == 3 then
            local scr = CfUtils.GetLuaScr(_go, "Game.Behaviours.GoodNodeMB")
            if scr then
                scr:SetSanXingGainShow(isPass)
            end
        end
        if type == 5 then
            local captainRewardDesc = go.transform:Find("TxtState")
            if isNotNull(captainRewardDesc) then
                KTool.SetActive(captainRewardDesc, true)
            end
        end
    end
end

