function UIActionPointMapDropMessagePopUpDialog:FillFirstReward()
    local t = RewardConfMgr:GetInstance():GetQuestRewardData(self.levelId, Constants.QuestRewardType.FristRewards)
    CfUtils.SetActive(self.FirstReward, table.count(t) > 0)

    for k, v in pairs(t) do
        local go = CfUtils.InstantiateGo(self.GoodNode, self.items)
        self:FillRewardGo(go, v)
    end
end

function UIActionPointMapDropMessagePopUpDialog:FillRewardGo(go, data)
    if not go or not data then
        return
    end
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self.levelId)
    CfUtils.SetActive(go, true)
    CfUtils.RefeshGoodGo2(go, data.goodsId, data.num, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    local scr = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
    if scr then
        scr:SetSanXingGainShow(isPass)
    end
end

function UIActionPointMapDropMessagePopUpDialog:FillBoxRewards()
    local t = RewardConfMgr:GetInstance():GetQuestRewardData(self.levelId, Constants.QuestRewardType.GoldBox)
    if table.count(t) > 0 then
        local go = CfUtils.InstantiateGo(self.cell, self.cont)
        self:FillBoxGroupReward(go, t, Constants.QuestRewardType.GoldBox, 3)
    end

    t = RewardConfMgr:GetInstance():GetQuestRewardData(self.levelId, Constants.QuestRewardType.SilverBox)
    if table.count(t) > 0 then
        local go = CfUtils.InstantiateGo(self.cell, self.cont)
        self:FillBoxGroupReward(go, t, Constants.QuestRewardType.SilverBox, 2)
    end

    t = RewardConfMgr:GetInstance():GetQuestRewardData(self.levelId, Constants.QuestRewardType.CopperBox)
    if table.count(t) > 0 then
        local go = CfUtils.InstantiateGo(self.cell, self.cont)
        self:FillBoxGroupReward(go, t, Constants.QuestRewardType.CopperBox, 1)
    end
end

function UIActionPointMapDropMessagePopUpDialog:FillBoxGroupReward(go, data, type, ind)
    if not go or not data then
        return
    end
    CfUtils.SetActive(go, true)
    CfUtils.SetUISwitchImage(go.transform:Find("title/img/ImgIcon/ImgChest"), 4 - ind)
    CfUtils.FillText(go.transform:Find("title/img/name"), GoodsUtils.GetRewardSourceDesc(type))

    local parGo = go.transform:Find("items")
    local goodsGo = parGo.transform:Find("GoodGroup")

    for k, v in pairs(data) do
        local groupGo = CfUtils.InstantiateGo(goodsGo, parGo)
        self:FillBoxRewardGo(groupGo, v)
    end
end

function UIActionPointMapDropMessagePopUpDialog:FillBoxRewardGo(go, data)
    if not go or not data then
        return
    end
    CfUtils.SetActive(go, true)
    CfUtils.RefeshGoodGo2(go.transform:Find("GoodPar/GoodNode"), data.goodsId, data.num, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    CfUtils.FillText(go.transform:Find("TxtProbability"), string.format('%g%%', checkNumber(data.probability) / 100))
end

